   "title": "微视频｜铭记历史 吾辈自强",
   "source": "大洋网·广州日报",
   "region": "全国",
   "url": "https://news.dayoo.com/china/202609/18/139997_55004880.htm",
   "date": "2026-09-18",
   "summary": "",
   "body": "1931年9月18日这一天，日本悍然发动震惊中外的九一八事变。铁蹄践踏，山河变色，生灵涂炭。\n从这一天起，中华民族开启了长达14年的浴血奋战。苦难与抗争，成为中华民族不能忘却的记忆。\n青山埋忠骨，山河念英魂。那永不熄灭的精神火炬，从历史烽燧间燎原而来，化为不灭的星火，照亮前行征程。\n硝烟散尽，天地间依然回荡着战斗的誓言。山河重光，新征程上回响着胜利的号角。\nhttps://news.dayoo.com/china/202609/18/139997_55004880.htm null 新华社 铭记历史，吾辈自强！ 1 0 1 /enpproperty--> [ 编辑： 佘湘娥 ] 免责声明：文中图片如有版权问题请联系网站处理，谢谢。 分享到： 广州 广东 社会 财经 国际 体育 热评 广州天河携AI硬核岗位，走进上财、复旦揽才 9月17日下午，“百万英才汇南粤”2026年N城联动秋季招聘活动上海财经大学专场在上海财经大学国定路校区科研实验大楼一楼报告厅举行。当天恰逢上财建校117周年校庆日，天河区携众多优质用人单位赴约上财，向财经学子发出“南粤邀请函”。\n为做实高校毕业生就业服务，精准提升驻穗高校学生职业规划水平与求职竞争力，广州市人力资源市场服务中心正式发布9月至12月“阳光就业·事业扬帆”公共就业指导进校园系列活动排期，超20场次公益职业指导课堂将陆续走进驻穗各大高校。\n九月的九龙湖，水面上不时有桨板和皮划艇划过。湖岸边，黄埔第一高楼知识塔近日亮灯；全球奢华度假品牌、广州首家悦榕庄已进入开业倒计时；水上运动中心每天迎来体验者，龙舟赛、研学、飞行营地等项目也陆续落地。\n广州早茶，是深植在城市基因里的生活艺术，更是广州向世界展示的味觉名片。“一盅两件”里，承载着广府人从容自在、开放共融的生活态度，烟火气息与淡淡茶香交织出这座城市最温暖的图景。\n在天河公园小北门旁，一座面积为1135平方米的建筑静静矗立，这里就是广州市人大常委会创办的广州市全过程人民民主实践展示中心，承载着广州这座城市对全过程人民民主的深刻理解与扎实实践。\n9月16日，香港特区行政长官李家超在立法会会议上郑重宣读《香港特别行政区经济和社会发展第一个五年规划（2026—2030年）》。翻阅6万字的文本，透过字里行间，既读到东方之珠继往开来、稳步向前的底气、锐气与韧劲，更读到穗港两地相向而行、协同发力的清晰走向。\n广州城市管理，有了形象IP“城仔”。9月17日，广州市城市管理和综合执法局正式发布广州城管IP“城仔”。该形象以山羊为设计原型，搭配木棉红围巾与橙红木棉披风，融合广州“羊城”“花城”元素，呼应城市管理“精细”“柔和”与守护市容秩序的理念。\n第五届华语纪录电影大会将于2026年9月22日至24日在广州举办，作为大会主体单元的第五届华语纪录电影大会优秀纪录电影展映活动已于9月7日拉开序幕，并持续至9月30日。\n随着2026年秋季新兵运输任务的全面启动，一批批怀揣报国壮志的南粤儿女集结出发，即将奔赴祖国大江南北的火热军营。新兵转运是一场与时间赛跑的接力赛。\n​无人清扫设备自主作业，AI巡扫机器人穿梭展区，广州一批新能源环卫车辆集中全新亮相——9月17日，2026广州国际智慧环卫与清洁设备展览会在广州保利世贸博览馆开幕。展会持续至9月19日，展览面积达2.5万平方米，汇聚全国400余家环卫清洁与物业产业上下游参展商。\n6月27日起，广东在全网推出《思想耀岭南》系列视频。第一季共20集，20名对话嘉宾将分享他们在工作、生活中的所思所感，以个体视角讲述广东故事、大湾区故事、中国故事，持续推动党的创新理论“飞入寻常百姓家”。\n江门有超10万亩滨海盐渍滩地，仅台山市海宴镇片区就有1.3万亩，成片滩涂上，超高盐分、土壤板结、台风返盐三大难题长期制约土地利用，这片紧邻大海的滩涂只能常年抛荒，当地群众流传着“种啥都难长、长啥都不旺”的说法，大片优质土地资源闲置，成为制约江门市农业发展的核心瓶颈。\n在今年全国两会上，揭阳古城火爆“出圈”，让千年揭阳古城的活化成果走进全省、全国视野。在广东纵深推进“百千万工程”的背景下，揭阳立足千年古城独特文脉资源，以文塑城、以古润新，让老城肌理与现代风貌相得益彰，让千年文脉在新时代焕发全新活力。\n近期，惠州发布了《2026年惠州第二批人工智能场景需求和供给清单》（以下简称《清单》），50项场景需求、30项供给方案，叠加总投资117亿元的智算中心项目集中签约。\n东莞市横沥镇因拥有500年牛墟非遗而被人称为“牛”镇。今年以来，横沥镇深入推进“百千万工程”，推出常态化文旅IP“潮‘牛’周末 IN 横沥”，跳出“一次性办节”，全年“细水长流”，盘活各村农、文、旅、商资源，以周末短途休闲游的流量和留量，激发乡村内生动力。\n思想政治工作是党的优良传统、鲜明特色",
