   "body": "1934年10月25日起，中央红军长征主力部队转战粤北，先后经过南雄、仁化、乐昌、连县（今连州）等地，成功突破敌人封锁线，向湖南方向挺进。红军过境粤北，是万里征途中的短暂一程，却铸就了不朽的丰碑。\n2025年11月，习近平总书记在广东考察调研时强调，教育引导广大干部群众特别是青少年传承红色基因、赓续红色血脉，永远听党话、跟党走。\n90余载岁月流转，粤北大地上，红军歌传唱不息，珍贵物件被悉心珍藏，烈士墓前祭扫的人们络绎不绝……忠烈为人铭记，薪火照亮征程。如今，各地依托资源禀赋，把红色资源与绿色生态、特色产业发展结合起来，一幅幅产业兴、百姓富、乡村美的画卷，正徐徐铺展。\n在广东省韶关市南雄市油山镇上朔村，村民们常常唱起这首《当红军歌》。在村中徐氏祠堂门廊左壁上，一方玻璃保护罩内，保留着它高1.5米、宽1.4米的手写歌谱。\n这是南雄目前发现的唯一一首有曲谱、有歌词、能传唱的完整红军歌曲。\n广东省韶关市南雄市油山镇上朔村墙壁上的《当红军歌》歌谱。（受访者供图）\n南雄市史志办主任黄树材介绍，据《上朔村志》记载，1929年至1934年，红军部队多次在上朔村活动。其间，写下了这首《当红军歌》。1934年10月下旬，红一军团取得长征入粤第一仗新田战斗的胜利后，来到上朔村休整宿营，在此期间，他们书写标语、作动员宣讲，教唱《当红军歌》，号召村里年轻人当兵就要当红军。\n红军离开上朔村后，村民用稻草和黄泥盖住词曲，才把它保留下来。如今，这首歌被编入油山镇小学的校本教材。孩子们不仅传唱《当红军歌》，还主动加入红色宣讲队伍，化身“小小红色讲解员”，向更多人讲述当年的军民鱼水深情。\n“会做工的有工做，会作田的有田耕”——90多年前，红军教唱的这句歌词，如今变成乡村振兴的现实图景。\n产业振兴，是乡村振兴的重中之重。近年来，南雄市着力盘活闲置资源，激活乡村发展动能，把车间建在群众家门口，让村民顾家挣钱两不误。当地将旧校舍、旧厂房改造为“乡村振兴车间”，积极引入培育企业，形成了电子元器件、农副产品、竹木加工等车间集群。\n一个个家门口的车间，串起了产业链，也让村民的“钱袋子”鼓起来。截至目前，南雄市累计建成乡村振兴车间284家，带动就业超6000人，实现产值约17.5亿元。\n在广东省韶关市红军长征粤北纪念馆，一只瓷碗，引得不少游客驻足。\n“湘有半条红军被，粤有一只红军碗。”纪念馆讲解员谭雅文介绍，这只承载军民情深的红军碗，由当地一家五代人守护，直至2019年捐赠给仁化县史志办公室保管，2026年移至纪念馆展出。\n广东省韶关市红军长征粤北纪念馆内的红军碗。新华社记者钟焯 摄\n1934年11月，中央红军主力途经韶关市仁化县城口镇，一位徐姓排长因重伤无法随军前行，东坑村村民蒙家财夫妇冒险收留照料，直到他伤势好转。临走时，徐排长把随他行军打仗吃饭用的瓷碗，塞到蒙家财手中说，等革命胜利了，一定回来报恩。\n然而，这份约定，未能兑现。这只瓷碗，由蒙家五代人接力守护，守护的不仅是一份未竟的承诺，更是一段不灭的红色记忆。\n近年来，韶关市仁化县着力将“红色资源”转化为经济发展优势，制定了红色旅游发展规划，将红军长征遗址遗迹集中的城口镇打造成“红色特色小镇”。\n每逢周末或节假日，红军街上游人如织，不少红色主题研学团队到此参观。据统计，2025年城口镇接待游客近30万人次，带动旅游综合收入3000余万元，带动周边村民人均年增收超千元。\n一条红军街，承载着军民鱼水的深情；一只瓷碗，背后是五代人的接力守护；一段长征故事，激荡着跨越时空的精神回响。城口镇以这些红色印记为纽带，将历史与当下紧紧相连，在传承中发展、在发展中传承，让“红色名片”愈发鲜亮。\n每年农历五月初九，在广东省清远市连州市瑶安瑶族乡田心村，村民们会上山给一座红军烈士墓祭扫。\n田心村党总支书记盘美艳介绍，这一天是村里定下的“红军节”。\n1935年1月，红五军团第三十四师余部，在田心村牵牛岭与敌人激战一天。红军战士浴血奋战，有6名战士不幸牺牲。村民们找到他们的遗体，合葬在这座没有姓名的红军烈士墓。\n位于广东省清远市连州市瑶安瑶族乡田心村的红军烈士墓。（受访者供图）\n硝烟散尽，但瑶乡儿女始终铭记英烈风骨。2017年，田心村集体出资修缮红军烈士墓，并设立“红军节”。\n近年来，连州市大力推进长征国家文化公园（广东段连州片区）项目建设，并加快统筹红色资源保护利用、乡村振兴与生态旅游，迈出融合发展的坚实一步。通过深入挖掘红色故事、宣讲红色文化，长征精神不断激励当地发展。\n依托得天独厚的自然禀赋，连州市做强特色农业，提升农产品附加值。当地发挥龙头企业带动作用，联农带农，推进菜心种植标准化、规模化，建成多处连片高标准种植基地，持续擦亮“连州菜心”特色品牌；同时延伸产业链条，深挖菜心附加值：采收后的菜心迅速送入预冷车间，产业园内分拣、包装、冷链物流",
   "tags": [
    "乡村振兴",
    "广东"
   ],
