   "title": "第23届中国—东盟博览会：从“共享机遇”到“共建生态”",
   "source": "大洋网·广州日报",
   "region": "全国",
   "url": "https://news.dayoo.com/china/202609/18/139997_55004882.htm",
   "date": "2026-09-18",
   "summary": "",
   "body": "9月17日至21日，第23届中国—东盟博览会（以下简称“东博会”）在广西南宁举行。本届东博会以“共享3.0机遇，共创美好生活”为主题，展览总面积达17万平方米，比去年增长约6%；超3400家企业参展，设南宁国际会展中心、南A社区、桂林国际会展中心三个展区，会期计划举办经贸活动约50场。\n自2004年首届东博会举办以来，这一盛会已走过20余载。从最初的商品展销平台，到如今涵盖经贸合作、产业对接、人文交流的综合性盛会，东博会见证了中国与东盟关系从“黄金十年”迈向“钻石十年”的全过程。本届东博会适逢中国—东盟建立全面战略伙伴关系5周年，自贸区3.0版升级议定书签署并即将实施，又迎来东帝汶首次以东盟正式成员国、东博会共办方身份亮相——东盟扩容后11个成员国首次齐聚南宁，实现了历史性的“全家福”。\n本届东博会最核心的背景，是自贸区3.0版升级议定书的签署与即将实施。与以往侧重关税减让的版本不同，3.0版首次将数字经济、绿色经济、产供链互联互通等新兴领域纳入制度化框架，推动区域经贸合作从“关税减让”迈向“规则协调”的制度型开放新阶段。\n这一制度升级有着坚实的贸易数据支撑。2025年，中国与东盟双边贸易额首次突破万亿美元大关，达1.05万亿美元，中国连续17年保持东盟第一大贸易伙伴地位。2026年1月至7月，双边贸易总额达7444.1亿美元，同比增长24.7%，增速跑赢中国外贸大盘7.4个百分点。\n目前，中国对东盟中间品进出口额已占双边贸易总额的三分之二，双方经贸关系从简单的货物买卖转向产业链深度嵌套。正因如此，本届东博会首次设置东盟国家需求展区，中国—东盟博览会秘书处秘书长王继才对此解读道：“这一展区从过去展示‘中国能卖什么’，转向集中展示东盟国家‘想要什么’、需要什么技术和应用。”\n“魅力之城”展区是东博会上最具人文温度的存在。自2005年第2届东博会设立以来，这一展区已承载近190个（次）城市的流光记忆。本届“魅力之城”涵盖中国长春市、文莱斯里巴加湾市、柬埔寨磅士卑省、老挝塞公省、缅甸勃固省、菲律宾宿务省、新加坡、泰国东北地区、东帝汶包考市、越南安江省，印度尼西亚和马来西亚作整体展示。\n细观各城市的展示内容，可以发现一条清晰的逻辑：城市形象展示正在与产业合作精准对接。中国长春市将集中展示轨道交通、光电信息、航空航天等优势产业，并推介冰雪文旅资源，将“北国春城”的产业实力与地域特色融为一体。柬埔寨磅士卑省则更为务实，将举办专场推介对接会，直接推动中国企业与当地政府、产业园区开展项目对接。老挝塞公省把目光投向绿色未来，风电、太阳能等清洁能源项目成为展示亮点。新加坡聚焦“智启新机，链通全球”主题，展示现代化城市治理与科创发展优势。泰国东北部地区20个府集体亮相，以地理标志性产品为载体推介旅游资源与投资机遇。东帝汶包考市首次登上东博会舞台，展示本土文旅特色与新兴发展潜力。\n从城市名片到合作桥梁，“魅力之城”展区的功能迭代折射出中国—东盟地方合作从相遇相知走向相融共赢的深层逻辑。\n如果说“魅力之城”体现的是地方合作的广度，那么本届东博会首次推出的链主企业“以大带小”参展模式则展现了产业合作的深度。\n这一模式的创新之处在于由行业龙头企业牵头组团，带领产业链上下游企业共同亮相，全景展现全链条技术成果与系统解决方案。\n在智慧能源领域，中国大唐集团立足链主定位，联动明阳智能、世纪互联等企业，系统展示绿色能源核心技术与全场景零碳解决方案。中国大唐已连续22年参展，借助东博会平台在柬埔寨、缅甸、印度尼西亚等国落地水电和清洁煤电项目，推动国内技术标准与东盟当地产业深度融合。国家电投则牵头组织15家企业，重点展示具有自主知识产权的“国和一号”大型先进压水堆核电站项目，以及氢基能源全产业链产品和技术。在高端装备制造板块，国机集团发挥农业机械与冶金装备的双重链主引领作用，集中展示覆盖工程设计、装备制造、配套供应及工程服务全流程的全产业链集成能力。\n这一参展模式的迭代，本质上是对自贸区3.0版“产供链协同”方向的展会回应。当双边经贸合作从“卖单品”转向“建生态链”，展会平台也必须从“摆展品”升级为“搭生态”。\n此外，本届东博会还首次设立“AI大卖场”，70余家企业、500多款产品集中亮相，推动AI从技术展示转向落地应用。王继才用了一个生动的比喻：“去年东博会AI是‘秀场’，今年AI是‘商场’，让AI从‘看得见’变成‘带得走’。”首次设立未来空间和科创企业成长赋能展区，400多件新产品、100多项新技术将首发亮相。这些举措与链主企业参展模式形成互补——前者面向消费端和中小科创企业，后者面向产业端和大型链主企业，共同构建起多层次的合作生态。\n另一个值得关注的节点是，世纪工程平陆运河建成通航。广西壮族自治区党委常委、副主席卢新宁介绍：“平陆运河向南通江海，极大提升中国和东",
