   "summary": "",
   "body": "新华社河内/南宁9月17日电 第23届中国—东盟博览会17日如约启幕。广西南宁国际会展中心内，来自70多个国家及地区3400多家企业携特色产品亮相，展商与客商穿梭其间，洽谈交流之声此起彼伏。中国与东盟携手同行、共赴3.0之约，为区域经贸合作注入新动能。\n这是9月17日拍摄的广西南宁国际会展中心。9月17日，第23届中国—东盟博览会暨中国—东盟商务与投资峰会在广西南宁开幕，主题为“共享3.0机遇，共创美好生活”。新华社记者曹祎铭摄\n今年适逢中国—东盟建立全面战略伙伴关系5周年，也是《中国—东盟全面战略伙伴关系行动计划（2026—2030）》起始之年，还是中国—东盟自贸区3.0版升级议定书签署后加快落地实施的关键一年。本届东博会以“共享3.0机遇，共创美好生活”为主题，聚焦自贸区建设促进区域经济高质量发展，展示中国—东盟经贸合作的新成果、新亮点。从2004年至今，这一盛会见证了中国与东盟从对话关系到全面战略伙伴关系的进程，也记录着双方合作不断拓展、持续升级的足迹。\n数据是合作热度最直观的展示。2025年，中国与东盟贸易额首次突破万亿美元，达1.05万亿美元；2026年前7个月，双边贸易额达7444.1亿美元，同比增长24.7%。更值得关注的是结构之变：中间品贸易已占双边贸易总值的三分之二，双方正从“买来卖去”转向“产业共生”。支撑这一跃迁的，是已签署的中国—东盟自贸区3.0版升级议定书。它首次将数字经济、绿色经济、产供链互联互通等新兴领域纳入框架，推动双方合作从传统的关税减免迈向规则、规制、标准等领域的深度对接。\n在本届东博会现场，这种从“商品往来”向“产业协同、创新联动”的转变更加可感可触：首次设立的“AI（人工智能）大卖场”汇聚70多家企业、500多款消费类AI产品；首次设置的东盟国家需求展，从过去更多展示“中国能卖什么”，转向集中展示东盟国家“想要什么”；专设的平陆运河专题展区，让基础设施联通与经贸平台的叠加效应更加直观……这种供需对接模式的转变，折射出双方合作更加精准、务实。\n这种变化，同样体现在东盟各国参展方的选择中。柬埔寨邮电部、马来西亚科技部牵头组织本国高新企业参展，带来前沿技术与创新产品；越南贸易促进局组织本土采购商和工业园区团组赴会，与中国智能制造、智慧物流、城市治理等前沿技术与成熟解决方案定向对接；东盟展区参展行业从农业、手工业等传统领域拓展至数字通信、绿色环保、人工智能等高附加值领域……中国与东盟经贸合作领域持续拓展、层次不断丰富。\n35年前，中国与东盟从建立对话关系起步；今天，当自贸区3.0版将合作从“边境上”延伸至“边境后”，当东盟扩容后11国首次齐聚东博会，中国与东盟正以制度型开放锚定长期合作预期，以产业协同夯实合作根基。每一吨货物、每一笔订单、每一个在跨境供应链上受益的普通商户，都能感受到合作带来的温度和力量。\nhttps://news.dayoo.com/china/202609/18/139997_55004884.htm null 新华社 第23届中国—东盟博览会17日如约启幕。广西南宁国际会展中心内，来自70多个国家及地区3400多家企业携特色产品亮相，展商与客商穿梭其间，洽谈交流之声此起彼伏。中国与东盟携手同行、共赴3.0之约，为区域经贸合作注入新动能。 1 0 1 /enpproperty--> [ 编辑： 佘湘娥 ] 免责声明：文中图片如有版权问题请联系网站处理，谢谢。 分享到： 广州 广东 社会 财经 国际 体育 热评 广州天河携AI硬核岗位，走进上财、复旦揽才 9月17日下午，“百万英才汇南粤”2026年N城联动秋季招聘活动上海财经大学专场在上海财经大学国定路校区科研实验大楼一楼报告厅举行。当天恰逢上财建校117周年校庆日，天河区携众多优质用人单位赴约上财，向财经学子发出“南粤邀请函”。\n为做实高校毕业生就业服务，精准提升驻穗高校学生职业规划水平与求职竞争力，广州市人力资源市场服务中心正式发布9月至12月“阳光就业·事业扬帆”公共就业指导进校园系列活动排期，超20场次公益职业指导课堂将陆续走进驻穗各大高校。\n九月的九龙湖，水面上不时有桨板和皮划艇划过。湖岸边，黄埔第一高楼知识塔近日亮灯；全球奢华度假品牌、广州首家悦榕庄已进入开业倒计时；水上运动中心每天迎来体验者，龙舟赛、研学、飞行营地等项目也陆续落地。\n广州早茶，是深植在城市基因里的生活艺术，更是广州向世界展示的味觉名片。“一盅两件”里，承载着广府人从容自在、开放共融的生活态度，烟火气息与淡淡茶香交织出这座城市最温暖的图景。\n在天河公园小北门旁，一座面积为1135平方米的建筑静静矗立，这里就是广州市人大常委会创办的广州市全过程人民民主实践展示中心，承载着广州这座城市对全过程人民民主的深刻理解与扎实实践。\n9月16日，香港特区行政长官",
