   "summary": "",
   "body": "记者今天了解到，市场监管总局发布首个作弊特征领域的国家计量测试技术规范《电子计价秤作弊特征识别测试规范》，将自2027年1月1日起正式实施。\n电子计价秤作为常见的称重器具，在农贸市场、商超、流动摊位等应用广泛，截至目前，全国有电子计价秤433万台。电子计价秤计量准确性是称重和计价收费公平准确的基础和核心，直接关系到群众“菜篮子”和“钱袋子”。《规范》将作弊特征识别的系统性测试纳入国家计量技术规范体系，为作弊行为甄别与计量监管执法提供坚实技术支撑，主要有三大特点：\n创新采用负面清单判定模式。《规范》从称重和计价两大维度，对电子计价秤的作弊特征（欺骗性使用特征）进行识别测试、综合研判，清晰划定属于负面问题清单的监管执法硬杠杠。覆盖常见作弊表现形式。《规范》将电子计价秤作弊划分为软件篡改、硬件改装两大类型。结合计量检定工作实操经验，在重点核查“缺斤短两”称重问题的基础上，同步把价格计算异常纳入测试重点，基本覆盖市场上各类常见的作弊手段，进一步织密民生计量监管网络。细化明确完整测试实操流程。《规范》厘清了作弊特征检测测试全流程，通过各类可能的按键组合调试、外部遥控装置模拟等方式甄别作弊行为，同时配合加载砝码、价格核验等手段，核查称重计价示值是否准确等，全链条全环节全要素甄别电子计价秤作弊特征，筑牢民生计量监管的技术底座。\nhttps://dayooimg.dayoo.com/Finance/202609/18/55004909_t1_13X26X587X349_69c87c54-576e-484e-804b-ea00a6d31aa1.jpg https://dayooimg.dayoo.com/Finance/202609/18/55004909_t1_13X26X587X349_69c87c54-576e-484e-804b-ea00a6d31aa1.jpg https://news.dayoo.com/finance/202609/18/171077_55004909.htm null 央视新闻客户端 记者今天了解到，市场监管总局发布首个作弊特征领域的国家计量测试技术规范《电子计价秤作弊特征识别测试规范》，将自2027年1月1日起正式实施。 1 0 0 /enpproperty--> [ 编辑： 佘湘娥 ] 免责声明：文中图片如有版权问题请联系网站处理，谢谢。 分享到： 广州 广东 社会 财经 国际 体育 热评 广州天河携AI硬核岗位，走进上财、复旦揽才 9月17日下午，“百万英才汇南粤”2026年N城联动秋季招聘活动上海财经大学专场在上海财经大学国定路校区科研实验大楼一楼报告厅举行。当天恰逢上财建校117周年校庆日，天河区携众多优质用人单位赴约上财，向财经学子发出“南粤邀请函”。\n为做实高校毕业生就业服务，精准提升驻穗高校学生职业规划水平与求职竞争力，广州市人力资源市场服务中心正式发布9月至12月“阳光就业·事业扬帆”公共就业指导进校园系列活动排期，超20场次公益职业指导课堂将陆续走进驻穗各大高校。\n九月的九龙湖，水面上不时有桨板和皮划艇划过。湖岸边，黄埔第一高楼知识塔近日亮灯；全球奢华度假品牌、广州首家悦榕庄已进入开业倒计时；水上运动中心每天迎来体验者，龙舟赛、研学、飞行营地等项目也陆续落地。\n广州早茶，是深植在城市基因里的生活艺术，更是广州向世界展示的味觉名片。“一盅两件”里，承载着广府人从容自在、开放共融的生活态度，烟火气息与淡淡茶香交织出这座城市最温暖的图景。\n在天河公园小北门旁，一座面积为1135平方米的建筑静静矗立，这里就是广州市人大常委会创办的广州市全过程人民民主实践展示中心，承载着广州这座城市对全过程人民民主的深刻理解与扎实实践。\n9月16日，香港特区行政长官李家超在立法会会议上郑重宣读《香港特别行政区经济和社会发展第一个五年规划（2026—2030年）》。翻阅6万字的文本，透过字里行间，既读到东方之珠继往开来、稳步向前的底气、锐气与韧劲，更读到穗港两地相向而行、协同发力的清晰走向。\n广州城市管理，有了形象IP“城仔”。9月17日，广州市城市管理和综合执法局正式发布广州城管IP“城仔”。该形象以山羊为设计原型，搭配木棉红围巾与橙红木棉披风，融合广州“羊城”“花城”元素，呼应城市管理“精细”“柔和”与守护市容秩序的理念。\n第五届华语纪录电影大会将于2026年9月22日至24日在广州举办，作为大会主体单元的第五届华语纪录电影大会优秀纪录电影展映活动已于9月7日拉开序幕，并持续至9月30日。\n随着2026年秋季新兵运输任务的全面启动，一批批怀揣报国壮志的南粤儿女集结出发，即将奔赴祖国大江南北的火热军营。新兵转运是一场与时间赛跑的接力赛。\n​无人清扫设备自主作业，AI巡扫机器人穿梭展区，广州一批新能源环卫车辆集中全新亮相",
