   "title": "马龙入学北京体育大学，开启读博生涯",
   "source": "大洋网·广州日报",
   "region": "全国",
   "url": "https://news.dayoo.com/sports/202609/18/140001_55004864.htm",
   "date": "2026-09-18",
   "summary": "",
   "body": "9月17日，北京体育大学举行2026年开学典礼。马龙、冯雨、李雪芮、张常宁等奥运冠军、世界冠军以新生的身份，在北体大开启新的篇章。\n新学期，马龙、冯雨、李雪芮、张常宁等奥运冠军成为北体大博士生。陈嘉堃摄\n“此刻，同学们身着同样的服装，拥有了共同的名字——北体人。北体，是我们共同的新一程。”北京体育大学党委书记樊战备代表学校对新生表示热烈欢迎，并嘱咐大家要做到“崇德修身、博学笃行、身心俱健”。\n乒乓球运动员马龙如今有了新的身份——北京体育大学2026级博士生。\n作为2026级冠军新生代表，马龙与花样游泳运动员冯雨向学校赠送签名纪念衫。2024年巴黎奥运会上，马龙和冯雨共同担任中国体育代表团开幕式旗手，并在当届比赛中都获得冠军。今年，他们一起成为了北体大博士生。\n北体大2026级博士生中还有谌龙、李雪芮、张常宁、孙一文等奥运冠军，硕士生和本科生中也有多位冠军运动员，新生“含金量”十足。身份转换后，这些冠军对于学习生活充满期待。\n羽毛球奥运冠军李雪芮说：“赛场教会我的是坚持与拼搏。来到校园，我希望与各位同学一起脚踏实地，勤学笃行，不负青春，不负时代。”\n张常宁希望把自己赛场上的实践经验和学术研究相结合，与同学们相互交流，共同进步。\nhttps://dayooimg.dayoo.com/Sports/202609/18/55004864_t1_0X60X319X239_81792104-63ca-4f4b-bb73-d71d56fdd89c.jpg https://dayooimg.dayoo.com/Sports/202609/18/55004864_t1_0X60X319X239_81792104-63ca-4f4b-bb73-d71d56fdd89c.jpg https://news.dayoo.com/sports/202609/18/140001_55004864.htm null 北京日报微信公众号 9月17日，北京体育大学举行2026年开学典礼。马龙、冯雨、李雪芮、张常宁等奥运冠军、世界冠军以新生的身份，在北体大开启新的篇章。 1 0 2 /enpproperty--> [ 编辑： 佘湘娥 ] 免责声明：文中图片如有版权问题请联系网站处理，谢谢。 分享到： 广州 广东 社会 财经 国际 体育 热评 广州天河携AI硬核岗位，走进上财、复旦揽才 9月17日下午，“百万英才汇南粤”2026年N城联动秋季招聘活动上海财经大学专场在上海财经大学国定路校区科研实验大楼一楼报告厅举行。当天恰逢上财建校117周年校庆日，天河区携众多优质用人单位赴约上财，向财经学子发出“南粤邀请函”。\n为做实高校毕业生就业服务，精准提升驻穗高校学生职业规划水平与求职竞争力，广州市人力资源市场服务中心正式发布9月至12月“阳光就业·事业扬帆”公共就业指导进校园系列活动排期，超20场次公益职业指导课堂将陆续走进驻穗各大高校。\n九月的九龙湖，水面上不时有桨板和皮划艇划过。湖岸边，黄埔第一高楼知识塔近日亮灯；全球奢华度假品牌、广州首家悦榕庄已进入开业倒计时；水上运动中心每天迎来体验者，龙舟赛、研学、飞行营地等项目也陆续落地。\n广州早茶，是深植在城市基因里的生活艺术，更是广州向世界展示的味觉名片。“一盅两件”里，承载着广府人从容自在、开放共融的生活态度，烟火气息与淡淡茶香交织出这座城市最温暖的图景。\n在天河公园小北门旁，一座面积为1135平方米的建筑静静矗立，这里就是广州市人大常委会创办的广州市全过程人民民主实践展示中心，承载着广州这座城市对全过程人民民主的深刻理解与扎实实践。\n9月16日，香港特区行政长官李家超在立法会会议上郑重宣读《香港特别行政区经济和社会发展第一个五年规划（2026—2030年）》。翻阅6万字的文本，透过字里行间，既读到东方之珠继往开来、稳步向前的底气、锐气与韧劲，更读到穗港两地相向而行、协同发力的清晰走向。\n广州城市管理，有了形象IP“城仔”。9月17日，广州市城市管理和综合执法局正式发布广州城管IP“城仔”。该形象以山羊为设计原型，搭配木棉红围巾与橙红木棉披风，融合广州“羊城”“花城”元素，呼应城市管理“精细”“柔和”与守护市容秩序的理念。\n第五届华语纪录电影大会将于2026年9月22日至24日在广州举办，作为大会主体单元的第五届华语纪录电影大会优秀纪录电影展映活动已于9月7日拉开序幕，并持续至9月30日。\n随着2026年秋季新兵运输任务的全面启动，一批批怀揣报国壮志的南粤儿女集结出发，即将奔赴祖国大江南北的火热军营。新兵转运是一场与时间赛跑的接力赛。\n​无人清扫设备自主作业，AI巡扫机器人穿梭展区，广州一批新能源环卫车辆集中全新亮相——9月17日，2026广州国际智慧环卫与清洁设备展览会在广州保利世贸博览馆开幕。展会持续至9月19日，展",
