   "body": "经广州市人民政府批准，广州市将于9月19日（星期六，全民国防教育日）上午举行防空警报试鸣暨“羊城天盾-2026”城市人民防空演习。\n防空警报信号规定为：预先警报鸣36秒、停24秒，反复3遍，时间3分钟；空袭警报鸣6秒，停6秒，反复15遍，时间3分钟；解除警报连续鸣放3分钟。演习当天10:20—10:43在全市范围内进行防空警报试鸣，其中10:20—10:23试鸣预先警报，10:30—10:33试鸣空袭警报，10:40—10:43试鸣解除警报。\n届时，全市固定警报器、机动防空警报车及部分多媒体多功能防空防灾预警报知系统，同时发放防空警报信号；广州市广播电视台综合频道和新闻资讯广播（FM96.2MHz）、金曲音乐广播（FM102.7MHz）、经济交通广播（FM106.1MHz）频道、广州地铁电视将同步发放防空警报信号；中国电信广州分公司、中国移动广州分公司、中国联通广州分公司将以手机短信息、微信、微博等方式，适时发布防空警报试鸣信息。\n防空警报试鸣期间，除在部分社区、机关、学校等开展疏散掩蔽、消除空袭后果等内容的防空演练外，全市生产、生活秩序及社会活动照常进行。\n今年是广州市连续第27年组织防空警报试鸣暨“羊城天盾”城市人民防空演习，将组织部分单位、专业力量、基层力量和城镇居民参加实战化演习，加强联防指挥和行动协同，推动城市人民防空和应急应战一体化走深走实。\n据悉，广州市连续三次被评为“全国人民防空先进城市”、广州市人防办连续三次被评为“全国人民防空先进单位”。广州市已连续26年成功举行防空警报试鸣暨“羊城天盾”城市人民防空演习，有关经验做法得到国家人防部门充分肯定，“羊城天盾”已从城市人民防空演习的单一标志，逐步形成广州人防“服务社会、造福于民”的知名品牌，打造为全国人防系统的响亮名片。\n为进一步增强广大市民群众国防观念和人防意识，更大范围普及基层群众防护知识，提升应对现代空袭手段的防护技能，近日广州市人民防空办公室结合防空警报试鸣暨“羊城天盾-2026”城市人民防空演习，在全市范围内广泛开展人民防空宣传教育进机关、进学校、进企业、进社区、进网络“五进”活动，大力营造社会各方关心人防、支持人防的良好氛围，切实增强战时防空、平时服务、应急支援的综合防护能力。\nhttps://news.dayoo.com/guangzhou/202609/17/139995_55004731.htm null 大洋网 经广州市人民政府批准，广州市将于9月19日（星期六，全民国防教育日）上午举行防空警报试鸣暨“羊城天盾-2026”城市人民防空演习。 1 0 2 /enpproperty--> [ 编辑： 李 健 ] 免责声明：文中图片如有版权问题请联系网站处理，谢谢。 分享到： 广州 广东 社会 财经 国际 体育 热评 全国首家全过程人民民主实践展示中心在广州开馆 9月17日，由广州市人大常委会创办的广州市全过程人民民主实践展示中心正式开馆并免费向公众开放。\n9月17日，由厦深铁路广东有限公司建设管理、中铁建工集团承建的深江铁路广州南沙站项目迎来关键节点，首块底板混凝土浇筑施工圆满收官。\n9月19日，天宇将为公众送上一份“双份年度之最”的浪漫礼物。金星作为“长庚星”将迎来年度的“高光”时刻；与此同时，本年度“最小的上弦月”也将在同一天亮相天幕，两大看点“同框”，值得抬头一看。\n9月17日，广州市交通运输局发布关于征求调整公共汽车427路等线路意见的公示。其中提到，根据公交出行需求变化情况，为优化公交线网布局，提高公交资源利用效率，计划调整公共汽车427路等线路行经路段，暂停运营公共汽车421路等线路。\n9月17日下午，一场聚焦汽车零部件出海的供需对接会在广州民营科技园举行，园区汽车零部件、养护用品及跨境电商等领域的约三十家企业负责人齐聚一堂，用“5分钟速配”的方式亮产品、链资源、找伙伴。此次活动由广州民营科技园管理委员会指导，广州民营科技园商会主办，广州拓华智造科技有限公司承办，旨在赋能园区企业抱团掘金海外市场。\n从上海交大到广州南沙，港科大（广州）博士新生黄清昊选择了一条与众不同的开学路——从本科母校上海交通大学出发，历时14天，累计骑行超1200公里，抵达位于广州南沙的港科大（广州）报到。\n眨眼间，北方已经有众多城市入秋，广州这边离了空调还热得慌。天气炎热的一个佐证，是热带气旋仍然活跃，今年第25号台风“杜鹃”已于昨天夜间生成，未来10天，南海及西北太平洋还可能有1～2个热带系统生成。“杜鹃”对我国近海无影响，广州的酷热天气未来三天将会持续，周末有35℃高温。\n经广州市人民政府批准，广州市将于9月19日（星期六，全民国防教育日）上午举行防空警报试鸣暨“羊城天盾-2026”城市人民防空演习。\n海洋是高质量发展的战略要地，海洋经济已成为国民经济的重要",
