   "body": "海洋是高质量发展的战略要地，海洋经济已成为国民经济的重要增长极。《广州市海洋经济发展“十五五”规划》已于近期印发公布，这是国务院赋予广州“彰显海洋特色的现代化城市”定位以来，首个海洋经济发展五年规划。\n9月17日上午，广州市人民政府新闻办公室召开《广州市海洋经济发展“十五五”规划》（下称《规划》）新闻发布会，市规划和自然资源局、市科技局、市工业和信息化局、市港务局的相关负责人介绍了《规划》的特色和亮点，以及接下来推动广州海洋经济高质量发展的举措和部署。\n《规划》提出，到2030年广州海洋生产总值突破7300亿元，较2025年的5231亿元增长超过2000亿元，基本建成彰显海洋特色的现代化城市，海洋经济综合竞争力大幅跃升。\n广州市规划和自然资源局（广州市海洋局）副局长姜莉介绍：“围绕该目标，未来广州将从科技创新、重点产业、空间保障、人海和谐、开放合作五大领域重点发力。”\n聚焦科技创新，构建从基础研究、技术攻关到成果转化、场景应用的全链条海洋科技创新体系。部署4项重点任务：一是实施海洋战略科技力量集聚行动。保障“梦想”号大洋钻探船高水平运行，推进冷泉生态系统研究装置建设，争取国家级科研平台落地，布局“空天地海网”一体化数字基础设施。二是大力推进海洋科技创新策源地建设。强化基础理论与底层技术系统布局，攻关深海极地、绿色低碳、数字智能等前沿科技，突破深海耐压材料、智能感知、水下超高速航行等“卡脖子”技术。三是构建海洋科技成果转化平台矩阵。加快布局船舶海工、智能装备等概念验证与中试验证平台，推动重大科研基础设施开放共享，加快建设南沙深海资源商业化开发应用场景创新试验区。四是完善科教研产一体化人才体系。引进海洋领域科学家、高层次研究人才及团队，支持海洋院士工作站和人才驿站建设，推动高校设立海洋新兴交叉学科，培养船舶制造等领域技能人才。预期到2030年，涉海科技创新平台增至170个、涉海概念验证平台和中试验证平台新增5个、涉海专精特新中小企业新增500家。\n聚焦重点产业，培育壮大海洋新质生产力，加速构建现代海洋产业体系。部署5项重点任务：一是推动船舶海工装备产业链条延伸、集群共进。加快船舶海工制造向高端化、绿色化、智能化转型，建设龙穴岛、小虎岛等船舶制造园区以及大岗等配套产业园，推动核心科技攻关，做强深海极地特色海工装备，发展船用动力系统等配套设备产业，拓展船舶检验认证等专业服务业。二是进一步强化国际航运枢纽能级。推进南沙港区五期、国际通用码头等重大工程建设，进一步做强多式联运，拓展港口腹地和船舶交易、航运融资租赁等高端业务，做强海商法律仲裁服务。三是打造特色海洋文化旅游业。推进海上丝绸之路申报世界文化遗产，拓展邮轮“一程多站”国际航线，完善游艇码头与口岸通关服务，建设南沙国际帆船运动中心，培育海洋文商旅体融合IP。四是壮大海洋新兴产业。加快发展海洋药物和生物制品业，壮大海洋电子信息产业，建设海洋AI基础大模型，构建现代化海洋牧场全产业链，集中攻关重防腐涂料等海洋高端新材料，建立红树林等蓝碳生态产品价值实现机制，促进“海洋+低空航天”融合发展。五是抢抓深海发展新机遇，加快深海产业落地。攻关深海探测采矿装备，发展深海探矿采矿产业链，加速推进天然气水合物产业化进程，推动“海洋能+”融合发展，发掘利用深海生物遗传资源，构建“探采藏测评用”全链条服务体系。预期到2030年，海洋制造业规模突破1400亿元、涉海“四上”企业新增1800家。\n聚焦空间保障，大力推动空间资源精准匹配海洋产业发展需求，重点建设“一带三区”和八大海洋产业园区。统筹珠江—狮子洋—伶仃洋沿岸资源打造海洋创新发展带，牵引南部、东部、中部三大海洋创新区错位发展。加快建设龙穴岛、大岗、小虎岛—广州沙仔岛等八大海洋特色产业园，促进海洋创新资源向重点片区园区集中，打造若干百亿级海洋产业集群。\n聚焦人海和谐，加强海洋生态资源高水平保护利用，不断满足人民群众对亲海空间的美好向往。一是推进海域空间多功能立体化利用，探索海洋资源生态补偿路径。二是推进水系连通，重点保育莲花山等3条山海通廊，加强南沙湿地等滨海红树林保护修复，严格保护自然岸线，系统整治修复受损岸线。三是实施海鸥岛等一批水体环境综合整治提升工程，稳步改善近岸海域水质。四是构建岸基、海基、空基、天基一体化海洋气象综合观测系统，提升海洋防灾减灾和应急能力。\n聚焦开放合作，充分发挥粤港澳大湾区核心引擎优势，推动海洋开放。一是协同发展海湾经济。深化与香港在航运物流、金融、海事服务等领域合作，协同大湾区发展海上风电、船舶海工等产业集群，联动粤东粤西建设“海域跨界合作区”及“飞海”。二是深化区域海洋合作。推动与海南自贸港“一单制”多式联运互认，对接西部陆海新通道，构建“粤港澳—北部湾—东盟”跨境物流走廊。三是拓展国际“蓝色朋友圈”。牵头国际大科学计",
