   "body": "2021年9月17日，横琴粤澳深度合作区管理机构正式揭牌成立，粤澳两地开启“共商共建共管共享”的开创性实践。历经五年深耕建设，合作区持续推进硬联通、软联通、心联通建设，琴澳一体化发展实现跨越式跃升，成为丰富“一国两制”实践的新示范、粤港澳大湾区建设的新高地、国家高水平对外开放的新平台。\n五年来，横琴粤澳深度合作区产业集聚效应持续释放，经济结构不断优化。合作区聚焦科技研发与高端制造、中医药等澳门品牌工业、文旅会展商贸、现代金融“四新”重点产业方向，推动产业发展与澳门发展定位深度协同，产业发展质效持续提升。数据显示，去年合作区“四新”产业增加值占GDP比重达67.1%，今年二季度攀升至68.1%。截至8月末，合作区实有澳资企业达8224户，占合作区企业总量16.40%。\n围绕企业培育发展，合作区搭建系统化企业扶持培育体系，打通科研、资本、场景、数据各类要素资源，分层分类赋能市场主体成长，着力培育专精特新企业集群，推动更多优质项目对接澳门科技发展规划，夯实产业创新发展根基。人才引育体系持续完善，澳琴人才卡正式发布，不断集聚各方人才投身合作区建设，为产业高质量发展积蓄智力动能。\n制度创新持续突破，琴澳规则衔接机制对接取得系列标志性成果。依托顶层设计赋能，分线管理、多功能自由贸易账户（EF账户）等政策相继落地，总体规划正式发布，双15%税收优惠、鼓励类产业目录、“海关新23条”措施等陆续到位。\n中央出台专项政策包为合作区第二阶段建设提供坚实支撑。澳门深度参与合作区建设全过程，将深化澳琴一体化纳入本地中长期发展规划，布局澳门国际机场横琴前置货站等一批重大标志性工程。跨境物流实现重大突破，推动澳门机场相关功能延伸至横琴，打通跨境货物高效流转通道。医药产业协同机制不断创新，搭建创新中成药研发注册协同通道，落地“澳门监造”“澳门监制”“澳门设计”等特色标志制度，实现两地产业优势互补。跨境电商新业态顺利落地，政策红利持续转化为企业实实在在的发展竞争力，推动澳门自由港制度优势在合作区延伸放大。\n民生融合走深走实，宜居融通的生活共同体加快成型。大量澳门居民选择在合作区就业、生活、居住，跨地域生活就业逐步成为常态。教育供给实现跨越式扩容，短时间内多所幼儿园、中小学、高校集中建成投用，澳琴国际教育（大学）城落地运行，构建起从学前教育到高等教育的完整办学链条，澳人子弟享受连贯的教育配套。作为面向澳门居民打造的居住社区，澳门新街坊已形成成熟居住氛围，社区配套全面对接澳门标准，公共服务、社会服务设施一应俱全，大批澳门居民在此安家生活。\n基础设施硬联通不断提质升级。横琴口岸通关智能化改造落地，通关效率进一步提升，相关配套通道加快规划建设，高铁、城市轨道交通等重大交通项目稳步推进，不断织密琴澳互联互通交通网络。\n规则机制软联通持续提质增效。政务服务同城化水平持续提升，“澳事琴办”可办理澳门政务服务事项拓展至470余项，落地内地首个澳门税务专属服务窗口、澳门政务线下服务专区，实现澳门公务员驻点服务。澳门社团持续扎根横琴，数量稳步增加。数字跨境服务平台建成上线，打通跨境就医、商业保险理赔等数据链路，不断破除两地民生服务壁垒。\n五年来，合作区坚持对标检验标准，持续夯实硬联通、优化软联通、深化心联通，不断推进琴澳一体化建设向纵深迈进。如今的横琴，已经成为澳门居民宜居兴业的重要新空间，越来越多澳门居民在此安居乐业。横琴粤澳深度合作区也在继续深化粤澳协同探索，持续释放琴澳叠加优势，以实干实践不断丰富“一国两制”的时代内涵。\nhttps://news.dayoo.com/guangdong/202609/17/139996_55004582.htm null 央视新闻客户端 2021年9月17日，横琴粤澳深度合作区管理机构正式揭牌成立，粤澳两地开启“共商共建共管共享”的开创性实践。历经五年深耕建设，合作区持续推进硬联通、软联通、心联通建设，琴澳一体化发展实现跨越式跃升，成为丰富“一国两制”实践的新示范、粤港澳大湾区建设的新高地、国家高水平对外开放的新平台。 1 0 6 /enpproperty--> [ 编辑： 佘湘娥 ] 免责声明：文中图片如有版权问题请联系网站处理，谢谢。 分享到： 广州 广东 社会 财经 国际 体育 热评 全国首家全过程人民民主实践展示中心在广州开馆 9月17日，由广州市人大常委会创办的广州市全过程人民民主实践展示中心正式开馆并免费向公众开放。\n9月17日，由厦深铁路广东有限公司建设管理、中铁建工集团承建的深江铁路广州南沙站项目迎来关键节点，首块底板混凝土浇筑施工圆满收官。\n9月19日，天宇将为公众送上一份“双份年度之最”的浪漫礼物。金星作为“长庚星”将迎来年度的“高光”时刻；与此同时，本年度“最小的上弦月”也将在同一天亮相天幕，两大看点“同框”，值得抬头",
