   "date": "2026-09-17",
   "summary": "",
   "body": "在第23届中国－东盟博览会暨中国－东盟商务与投资峰会开幕式上的致辞 （2026年9月17日，广西南宁） 中华人民共和国国务院副总理 丁薛祥\n大家上午好！金秋时节，丹桂飘香。很高兴同大家相聚广西南宁，共同出席第23届中国－东盟博览会暨中国－东盟商务与投资峰会开幕式。本届博览会、峰会以“共享3.0机遇，共创美好生活”为主题，具有重要现实意义。首先，我谨代表中国政府，对本届博览会和峰会的召开表示热烈祝贺！对各位嘉宾的到来表示诚挚欢迎！\n中国政府高度重视中国－东盟自由贸易区建设。2021年11月，习近平主席在中国－东盟建立对话关系30周年纪念峰会上，提出尽早启动中国－东盟自由贸易区3.0版建设，提升贸易和投资自由化便利化水平，拓展数字经济、绿色经济等新领域合作，为推动自贸区向更高水平发展指明了方向。\n中国－东盟自贸区的建设发展，走过了很不平凡的历程。2002年11月，双方签署《中国－东盟全面经济合作框架协议》，正式启动自贸区建设。2010年1月，中国－东盟自贸区1.0版如期建成，大范围实现零关税，开启中国－东盟经贸合作大步向前的新篇章。2019年10月，2.0版升级议定书全面生效实施，着重扩大服务领域开放和投资市场准入，推动双方经贸合作迈上新台阶。2022年11月，中国与东盟正式启动3.0版谈判，着力打造更加包容、现代、全面和互利的中国－东盟自贸区。经过双方共同努力，3.0版升级议定书已经正式签署，目前正在各自履行法律程序，推动尽早生效实施。\n中国－东盟自贸区建成以来，一直稳健运行，取得丰硕成果。双边贸易蓬勃发展。中国连续17年稳居东盟第一大贸易伙伴，东盟连续6年成为中国第一大贸易伙伴，2025年双边贸易总额突破1万亿美元，比2002年增长了18倍。投资合作持续深化。双向投资累计超过5100亿美元，一批重大合作项目扎实推进，中老铁路助力老挝从“陆锁国”变成“陆联国”，印尼雅万高铁铺就发展快车道。产业链供应链深度融合。中马、中印尼“两国双园”项目和中老跨境经济合作区建设稳步推进，跨境分工网络日益完善。民生福祉不断改善。经贸合作创造大量就业岗位，拓宽居民增收渠道，给双方民众都带来了实实在在的好处。在自贸区发展带动下，目前双方平均每天有十多万人员往来，相知相亲的民意基础越来越牢固。\n这些年，中国－东盟自贸区有力推动区域经济融合发展，成为双方命运共同体建设的重要载体。在变乱交织的国际形势下，本地区保持和平稳定和繁荣发展，政治互信更加巩固、开放合作不断深化、互联互通越发便利、人文纽带日益拉紧，中国－东盟自贸区发挥了重要作用，为全球南方国家实现共同发展树立了成功的典范。\n回首过去，已是硕果累累；展望未来，还需携手共进。中国－东盟自贸区3.0版升级议定书生效实施后，将同《区域全面经济伙伴关系协定》（RCEP）形成更为强劲的“双轮驱动”，为区域经济发展注入源源不断的新动能。下面，围绕建设好更高水平的中国－东盟自贸区，我愿提出4点建议。\n第一，推动区域开放水平全面提升。3.0版升级议定书立足地区特点和需要，借鉴国际高标准经贸规则，探索建立更为完善的合作框架和机制化安排，将为区域合作发展提供良好制度保障。我们要深化标准、技术法规、合格评定等领域合作，健全竞争和消费者保护、中小微企业等领域制度，加快建设开放、包容、以规则为基础的区域一体化大市场。中国将扩大高水平对外开放，以服务业为重点扩大市场准入和开放领域，同东盟共享发展机遇，促进区域经济深层次一体化和长期稳定增长。\n第二，推动贸易投资合作提质升级。中国和东盟人口占全球四分之一、经济总量超过23万亿美元，资源禀赋各异，产业互补性很强。双方对贸易投资自由化便利化作出更高水平的承诺和安排，体现了携手应对国际经贸挑战的信心和决心。我们要践行真正的多边主义，进一步拓展经贸合作深度和广度，共同维护地区和全球产业链供应链稳定畅通。中国愿发挥完整产业体系、超大规模市场等优势，加强双向投资合作，进口更多东盟优质产品，让合作成果更好造福地区人民。\n第三，推动新兴领域合作走深走实。将高水平开放合作拓展到数字经济、绿色经济等新兴领域，是中国和东盟自贸合作实践的新突破。我们要抓住新一轮科技革命和产业变革机遇，共同推进区域数字经济发展，深化人工智能等领域技术研发与场景应用合作，充分释放创新驱动效能。努力消除环境产品和服务贸易壁垒，推动绿色发展与经贸合作相互促进。中国愿同东盟加强经验交流，提供先进技术和产品，打造区域经济高质量发展新引擎。\n第四，推动互联互通更加便捷高效。中国和东盟山水相连，互联互通具有独特优势，也是经贸往来的重要支撑。我们要统筹推进铁路、公路、港口、机场等基础设施建设，协同推动“硬联通”和“软联通”，为区域经济一体化提供有力支撑。东南亚地区拥有众多优良深水港，中国与东盟货物贸易中六成以上通过海运实现。就在昨天，连接",
   "tags": [
    "高质量发展",
    "高水平开放"
   ],
