   "title": "特稿｜筑牢合作根基 共创美好未来——中国携手金砖国家共绘发展繁荣新画卷",
   "source": "大洋网·广州日报",
   "region": "全国",
   "url": "https://news.dayoo.com/china/202609/17/139997_55004786.htm",
   "date": "2026-09-17",
   "summary": "",
   "body": "新华社北京9月15日电 特稿｜筑牢合作根基 共创美好未来——中国携手金砖国家共绘发展繁荣新画卷\n“‘大金砖’要有大作为、实现大发展，就必须筑牢务实合作根基。”当地时间13日上午，习近平主席在新德里出席金砖国家领导人第十八次会晤第二阶段会议并发表重要讲话强调。\n今年是金砖国家合作20周年。金砖合作机制在新兴市场国家和发展中国家群体性崛起的历史大潮中应运而生，20年来始终坚持独立自主、联合自强，聚焦发展议题，推动务实合作，建立起全方位、多层次合作架构，成为当今世界最具影响力的新兴市场和发展中国家合作平台。\n作为金砖合作中坚力量、全球南方核心成员，中国始终秉持开放包容、合作共赢的金砖精神，勇做时代先锋，携手金砖国家筑牢务实合作根基，凝聚共同发展合力，壮大全球南方力量，为促进“大金砖合作”高质量发展和全球南方发展振兴持续注入澎湃动力。\n经过20年发展，如今的“金砖大家庭”人口占世界近一半，经济总量约占世界30%，贸易总额占世界五分之一，集聚“大富矿”、“大工厂”、“大市场”，体量和发展潜力可观。“金砖国家作为全球南方第一方阵，坚持独立自主，积极探索符合自身国情的发展道路，成为新兴市场和发展中国家联合自强的典范。”习近平主席在本次金砖会晤期间指出。\n无论是深化经贸合作、推动金融治理、建设新工业革命伙伴关系，还是弥合数字鸿沟、应对气候变化、加强产业链供应链等领域合作，金砖机制始终坚持发展优先，赋能更多发展中国家抓住时代机遇，探索可持续发展新路径。这一过程中，中方提出的全球发展倡议引领金砖机制下的务实合作项目蓬勃开展、走深走实。\n习近平主席指出：“中方提出全球发展倡议5年来，已经同各方共同开展2000多个合作项目，培训各类人才超过20万名，惠及120多个国家的人民。”\n位于福建省厦门市的金砖国家新工业革命伙伴关系创新基地，正是中国践行全球发展倡议、携手金砖伙伴共同发展的生动缩影。截至今年8月底，该基地成功举办60多场交流活动，开展90多期线上线下人才培训，累计签约138个合作项目，投资额超620亿元。\n“我们要发挥背靠新兴市场、联结全球南方的优势，坚持开放合作、互利共赢，维护产业链供应链稳定畅通，培育一体化大市场。”习近平主席的擘画和思考，始终着眼于为金砖合作增效、为全球南方赋能。\n作为习近平主席亲自关心和推动的金砖合作旗舰项目，金砖国家新开发银行以创新性融资机制和发展模式，为全球南方国家经济发展提供有力保障。截至2025年年底，该行已累计批准项目139个，融资总额约430亿美元，不仅成为国际金融体系新兴力量和全球南方合作的金字招牌，更为中国引领推动“大金砖合作”高质量发展写下鲜活注脚。\n“金砖合作机制在融资、基础设施、能源、贸易及政策协调等领域取得了实实在在的进展。新开发银行就是金砖国家最具代表性的机制性合作成果之一。”印度尼西亚大学东盟-中国研究中心主任韩培说，中国始终关注金砖国家共同利益，在以务实合作赋能共同发展方面发挥着关键引领作用。\n在金砖国家工商理事会南非理事会成员斯塔夫罗斯·尼古劳看来，习近平主席在本次金砖会晤期间提出建设金砖国家特殊经济区伙伴关系，并宣布中方将于明年举办金砖国家服务贸易论坛，培育经贸合作增长点，将进一步推动金砖国家互利共赢，为推动“大金砖合作”高质量发展汇聚更多合力。\n习近平主席在本次金砖会晤期间说，金砖国家要做促进创新发展的先锋。他强调，愿同各方共同打造更多研发和应用成果，深化产业链供应链合作。\n迈入“大金砖合作”高质量发展新阶段，金砖国家不断加速拓展智能制造、数字经济、人工智能等新领域新赛道合作，展现出强大的协同发展能力。\n从推动建立金砖国家特殊经济区中国合作中心、金砖国家工业能力中国中心，到金砖产业合作暨出海综合服务港为中国企业出海、金砖国家企业进入中国市场打造一站式服务枢纽，再到本次金砖会晤期间提议建设金砖国家特殊经济区伙伴关系、推动建立金砖国家数字产业云平台……中国的一系列举措以“实”字打底、从“新”处着力，契合各方发展需要，助力金砖机制发展能力与合作水平不断迈上新台阶。\n埃及贝尼苏韦夫大学政治与经济学院经济系主任穆罕默德·阿卜杜勒-加尼认为，习近平主席对金砖机制的长远擘画和细致规划，精准切中创新这一引领发展的第一动力。中国在推动创新发展上展现出长远眼光，是推动金砖国家合作的关键力量，引领金砖国家务实合作提质升级，持续迸发创新活力。\n“金砖国家要牢牢把握主动权，加强人工智能合作，鼓励开源开放、合作共享，推动务实合作向新而行、向高攀登。”本次金砖会晤期间，习近平主席围绕新一轮科技革命和产业变革，提出多项务实合作举措，致力于帮助全球南方国家提升能力、平等受益。\n从不久前携手各方推动成立世界人工智能合作组织，并面向金砖国家等建设国际人工智能应用合作中心，到提议建立金砖国家工程师培养联盟，提出实施金砖国家青",
