   "body": "一幅习近平同志在福建工作时的珍贵照片令人印象深刻，这是《闽山闽水物华新——习近平福建足迹》封面照片。画面呈现的是1999年11月，习近平同志在永定暴动旧址金谷寺前亲切看望“五老”人员的场景。画面中三位老人分别是：王振全，1921年生，永定上金村老游击队员；邱占林，1921年生，永定赤竹村老交通员；张日銮，1922年生，永定下金村革命群众代表。\n闽西是全国较早建立苏维埃政权和创建红军的地方，是中国共产党人继井冈山之后开辟的又一块巩固的革命根据地，是二十年红旗不倒的地方。一里一忠魂。在这里，2.6万多人参加长征，到达陕北仅剩约2000人，可以说每一华里都有一位闽西儿女倒下。闽西为长征的胜利付出了巨大牺牲，作出了重大贡献。\n在全国两会等诸多重要场合，习近平总书记一次次深情讲述闽西红土地上的峥嵘过往，让老区精神跨越岁月、直抵人心。\n在红军长征胜利90周年之际，我们循着习近平总书记当年踏访闽西的足迹，走到同他交谈过的老区群众身边，重忆暖心往事、见证山乡巨变，从红土地的故事里汲取奋进力量、传承精神根脉。\n青山如黛、溪水潺潺。闽西的青山绿水间，毗邻“龙岩八景”之一“奇迈岚光”的龙岩市新罗区邓厝村，一座座古厝见证着红色历史。这里是革命前辈邓子恢的故乡。\n村里有一口井，名为“思源泉”。思源泉的故事，在村里家喻户晓。\n党员干部在龙岩市新罗区东肖街道邓厝村思源泉前重温入党誓词。（本图片由新罗区委宣传部提供）\n1999年1月8日至12日，时任福建省委副书记习近平花了四天半的时间，走访部分闽西籍革命前辈的家乡，看望慰问老区群众。\n“那时正是春节前，天气很冷，路也不好走。习近平同志风尘仆仆走进革命先烈陈客嫲的女儿陈梅香老人家中时，老人眼中泛起了泪花。注意到陈梅香老人年事已高，听力不太好，习近平同志亲切拉起她的手，在耳边询问身体怎么样、家里有没有什么困难。”当时就在现场的邓厝村现任党支部书记邓学先告诉记者，习近平同志送给老人的电饭煲，至今还被珍藏着。\n了解到邓厝村还不通自来水后，习近平同志马上要求当地有关部门帮助解决。\n不久，10万元资金拨付到位，村里打井修池，全村人终于喝上了清洁的自来水，农田灌溉问题也得到解决。村民们把这口井命名为“思源泉”，希望后人“吃水不忘挖井人”。\n“当清甜的自来水流进村民家里，那欢天喜地的场景，比过年还热闹。”邓学先说。\n“饮水思源，勿忘老区。习近平总书记的深情牵挂，是对闽西儿女当年奉献牺牲的铭记。这告诉我们，党和人民始终心连心。”邓学先感铭于心。\n如今村里在保护好邓子恢故居、思源泉的基础上，秉持“有址可寻、有物可看、有史可讲、有事可说”，把红色资源变成活教材，打造沉浸式研学路线和乡村旅游动线，营造基层党建的实景课堂。\n“大家讲红色故事，不仅仅是讲过去的‘苦’，讲牺牲，也讲今天的‘甜’和未来的‘盼’。大家现在常挂在嘴边的就是‘饮水常思源’，把习近平总书记的关怀讲给孩子听、讲给游客听，这种自豪感是发自内心的。”邓学先说。\n龙岩市新时代文明实践中心志愿者在杨成武将军故居为党员干部宣讲。新华社发\n“习书记平易近人！”提起20多年前习近平同志到村里慰问的情景，杨成武将军故乡、长汀县下畲村时任村党支部副书记张维华竖起大拇指点赞。\n张维华记得，当时通往一户老红军家中的稻田路只有二三十公分宽，寒冬时节，十分泥泞，他想叫人找块木板垫着，习近平同志阻止了，坚持走群众走过的路。\n走访了几户人家后，大家在村部召开座谈会。习近平同志说：“革命老区和老区人民为中国革命胜利作出了重要贡献，党和人民永远不会忘记，让老区人民过上好日子，是我们党的庄严承诺。”\n这次闽西老区之行，习近平同志为龙岩协调各类扶持资金，重点解决水土流失、旧村改造等问题，为老区人民的生活带来真切变化。\n长汀，世界客家首府，红军长征出发地之一，被称为“红军故乡”。近代以来由于森林遭到严重破坏，长汀曾是全国最为严重的水土流失区之一。据1985年卫星遥感普查，长汀水土流失面积达146.2万亩，占全县国土面积的31.5%。\n在龙岩市长汀县南山镇拍摄的松毛岭战斗烈士纪念碑（无人机照片）。新华社记者 韩旭 摄\n而如今的长汀，汀江穿城而过，两岸绿意葱茏。站在高处望去，卧龙山的树一层叠一层，像墨绿的地毯铺到天边。\n“滴水穿石，人一我十，治理水土”的标语树立在村村寨寨，长汀县水土保持科教园里，20多年前种下的那棵香樟树已然枝繁叶茂，它们是一段历史的共同见证。\n“这里铭刻着红色长征的足迹，也书写了‘绿色长征’的奇迹。”在当年红九军团长征出发地长汀县中复村，原县委书记饶作勋讲述了前赴后继进行水土流失治理的故事。\n“作为一名在长汀工作8年的党员干部，我有幸能亲眼目睹长汀生态修复的过程，深切感受治荒山、拔穷根、摘穷帽的艰辛和不易，深切感受到由‘火焰山’到‘花果山’、从‘荒山浊水’到‘绿水青山’‘金山银山’的完美蜕",
